        "madc.lo.cc.u32 %1, %10, %12, %1;\n\t"
        "madc.lo.cc.u32 %2, %10, %13, %2;\n\t"
        "madc.lo.cc.u32 %3, %10, %14, %3;\n\t"
        "madc.lo.cc.u32 %4, %10, %15, %4;\n\t"
        "madc.lo.cc.u32 %5, %10, %16, %5;\n\t"
        "madc.lo.cc.u32 %6, %10, %17, %6;\n\t"
        "madc.lo.cc.u32 %7, %10, %18, %7;\n\t"
        "addc.u32       %8, %8, 0;\n\t"
        "mad.hi.cc.u32  %1, %10, %11, %1;\n\t"
        "madc.hi.cc.u32 %2, %10, %12, %2;\n\t"
        "madc.hi.cc.u32 %3, %10, %13, %3;\n\t"
        "madc.hi.cc.u32 %4, %10, %14, %4;\n\t"
        "madc.hi.cc.u32 %5, %10, %15, %5;\n\t"
        "madc.hi.cc.u32 %6, %10, %16, %6;\n\t"
        "madc.hi.cc.u32 %7, %10, %17, %7;\n\t"
        "madc.hi.cc.u32 %8, %10, %18, %8;\n\t"
        "addc.u32       %9, %9, 0;\n\t"
        : "+r"(r[7]), "+r"(r[8]), "+r"(r[9]), "+r"(r[10]), "+r"(r[11]), "+r"(r[12]), "+r"(r[13]), "+r"(r[14]), "+r"(r[15]), "+r"(r[16])
        : "r"(f[7]), "r"(g[0]), "r"(g[1]), "r"(g[2]), "r"(g[3]), "r"(g[4]), "r"(g[5]), "r"(g[6]), "r"(g[7]));

    // Reduce the 512-bit product. 2^256 = 38 (mod p), so the answer is
    // low(r[0..8]) + 38 * high(r[8..16]).
    u32 c[9];
    asm volatile(
        "mad.lo.cc.u32  %0, %9,  %17, 0;\n\t"
        "madc.lo.cc.u32 %1, %10, %17, 0;\n\t"
        "madc.lo.cc.u32 %2, %11, %17, 0;\n\t"
        "madc.lo.cc.u32 %3, %12, %17, 0;\n\t"
        "madc.lo.cc.u32 %4, %13, %17, 0;\n\t"
        "madc.lo.cc.u32 %5, %14, %17, 0;\n\t"
        "madc.lo.cc.u32 %6, %15, %17, 0;\n\t"
        "madc.lo.cc.u32 %7, %16, %17, 0;\n\t"
        "addc.u32       %8, 0, 0;\n\t"
        "mad.hi.cc.u32  %1, %9,  %17, %1;\n\t"
        "madc.hi.cc.u32 %2, %10, %17, %2;\n\t"
        "madc.hi.cc.u32 %3, %11, %17, %3;\n\t"
        "madc.hi.cc.u32 %4, %12, %17, %4;\n\t"
        "madc.hi.cc.u32 %5, %13, %17, %5;\n\t"
        "madc.hi.cc.u32 %6, %14, %17, %6;\n\t"
        "madc.hi.cc.u32 %7, %15, %17, %7;\n\t"
        "madc.hi.cc.u32 %8, %16, %17, %8;\n\t"
        : "=r"(c[0]), "=r"(c[1]), "=r"(c[2]), "=r"(c[3]), "=r"(c[4]),
          "=r"(c[5]), "=r"(c[6]), "=r"(c[7]), "=r"(c[8])
        : "r"(r[8]), "r"(r[9]), "r"(r[10]), "r"(r[11]), "r"(r[12]),
          "r"(r[13]), "r"(r[14]), "r"(r[15]), "n"(38));

    u32 top;
    asm volatile(
        "add.cc.u32  %0, %9,  %17;\n\t"
        "addc.cc.u32 %1, %10, %18;\n\t"
        "addc.cc.u32 %2, %11, %19;\n\t"
        "addc.cc.u32 %3, %12, %20;\n\t"
        "addc.cc.u32 %4, %13, %21;\n\t"
        "addc.cc.u32 %5, %14, %22;\n\t"
        "addc.cc.u32 %6, %15, %23;\n\t"
        "addc.cc.u32 %7, %16, %24;\n\t"
        "addc.u32    %8, %25, 0;\n\t"
        : "=r"(h[0]), "=r"(h[1]), "=r"(h[2]), "=r"(h[3]),
          "=r"(h[4]), "=r"(h[5]), "=r"(h[6]), "=r"(h[7]), "=r"(top)
        : "r"(r[0]), "r"(r[1]), "r"(r[2]), "r"(r[3]),
          "r"(r[4]), "r"(r[5]), "r"(r[6]), "r"(r[7]),
          "r"(c[0]), "r"(c[1]), "r"(c[2]), "r"(c[3]),
          "r"(c[4]), "r"(c[5]), "r"(c[6]), "r"(c[7]), "r"(c[8]));

    // `top` counts multiples of 2^256 still outstanding; fold them in as 38
    // each. `top` is small (below 2^6), so 38*top cannot overflow a limb.
    fe_fold_carry(h, top * 38u);
}

// h = f * f. Squaring admits a symmetry optimisation, but it is used almost
// only inside the exponentiation ladder, whose cost is amortised across a whole
// batch by Montgomery's trick.
__device__ __forceinline__ void fe_sq(fe h, const fe f) { fe_mul(h, f, f); }


// Load from 32 little-endian bytes. Bit 255 is masked off here, not by the
// caller: a compressed point carries the x sign there, and admitting it would
// silently accept values with no canonical representation.
__device__ __forceinline__ void fe_frombytes(fe h, const u8 *s) {
#pragma unroll
    for (int i = 0; i < FE_LIMBS; i++) {
        h[i] = (u32)s[4 * i] | ((u32)s[4 * i + 1] << 8)
             | ((u32)s[4 * i + 2] << 16) | ((u32)s[4 * i + 3] << 24);
    }
    h[7] &= 0x7fffffffu;
}

// Reduce to the canonical representative in [0, p).
//
// Done in two stages rather than by repeated conditional subtraction, because
// the input can exceed 2p and a single subtract-if-greater is then not enough.
//
//   1. Fold bit 255 down: 2^255 = 19 (mod p), so clearing that bit and adding
//      19 in its place leaves the value below 2^255 + 19.
//   2. That is at most p + 37, so exactly one conditional subtraction of p
//      finishes the job. Subtracting p is adding 19 and clearing bit 255, and
//      "is it at least p" is precisely "does adding 19 reach 2^255".
//
// Both steps are constant-time selects rather than branches.
__device__ __forceinline__ void fe_freeze(fe t, const fe h) {
    fe_copy(t, h);

    // Stage 1: fold bit 255.
    const u32 top = t[7] >> 31;
    t[7] &= 0x7fffffffu;
    fe_fold_carry_nowrap(t, top * 19u);

    // Stage 2: q = t + 19; t >= p exactly when bit 255 of q is set.
    u32 q[FE_LIMBS];
    asm volatile(
        "add.cc.u32  %0, %8,  %16;\n\t"
        "addc.cc.u32 %1, %9,  0;\n\t"
        "addc.cc.u32 %2, %10, 0;\n\t"
        "addc.cc.u32 %3, %11, 0;\n\t"
        "addc.cc.u32 %4, %12, 0;\n\t"
        "addc.cc.u32 %5, %13, 0;\n\t"
        "addc.cc.u32 %6, %14, 0;\n\t"
        "addc.u32    %7, %15, 0;\n\t"
        : "=r"(q[0]), "=r"(q[1]), "=r"(q[2]), "=r"(q[3]),
          "=r"(q[4]), "=r"(q[5]), "=r"(q[6]), "=r"(q[7])
        : "r"(t[0]), "r"(t[1]), "r"(t[2]), "r"(t[3]),
          "r"(t[4]), "r"(t[5]), "r"(t[6]), "r"(t[7]), "n"(19));

    const u32 mask = (u32)(-(i32)(q[7] >> 31));
    q[7] &= 0x7fffffffu;
#pragma unroll
    for (int i = 0; i < FE_LIMBS; i++) t[i] = (t[i] & ~mask) | (q[i] & mask);
}

// Store as 32 little-endian bytes, fully reduced.
__device__ __forceinline__ void fe_tobytes(u8 *s, const fe h) {
    fe t;
    fe_freeze(t, h);
#pragma unroll
    for (int i = 0; i < FE_LIMBS; i++) {
        s[4 * i]     = (u8)(t[i]);
        s[4 * i + 1] = (u8)(t[i] >> 8);
        s[4 * i + 2] = (u8)(t[i] >> 16);
        s[4 * i + 3] = (u8)(t[i] >> 24);
    }
}

// The first eight bytes of the canonical encoding, read big-endian: the
// prefilter probe. Limbs 0 and 1 are exactly bytes 0..7, so no bit shuffling is
// needed at all -- the saturated representation lines up with byte boundaries,
// which the radix-25.5 one did not.
__device__ __forceinline__ u64 fe_prefix_be64(const fe h) {
    fe t;
    fe_freeze(t, h);
    const u32 lo = t[0], hi = t[1];
    // Byte-reverse the 64-bit little-endian value; the compiler lowers each
    // 32-bit reversal to a single PRMT.
    const u32 a = __byte_perm(lo, 0, 0x0123);
    const u32 b = __byte_perm(hi, 0, 0x0123);
    return ((u64)a << 32) | (u64)b;
}

__device__ __forceinline__ u32 fe_isnonzero(const fe f) {
    fe t;
    fe_freeze(t, f);
    u32 acc = 0;
#pragma unroll
    for (int i = 0; i < FE_LIMBS; i++) acc |= t[i];
    return acc != 0;
}

__device__ __forceinline__ u32 fe_isnegative(const fe f) {
    fe t;
    fe_freeze(t, f);
    return t[0] & 1u;
}

// out = z^(2^252 - 3). Shared skeleton for inversion and square roots.
__device__ __noinline__ void fe_pow22523(fe out, const fe z) {
    fe t0, t1, t2;
    int i;
    fe_sq(t0, z);
    fe_sq(t1, t0); fe_sq(t1, t1);
    fe_mul(t1, z, t1);
    fe_mul(t0, t0, t1);
    fe_sq(t0, t0);
    fe_mul(t0, t1, t0);
    fe_sq(t1, t0); for (i = 1; i < 5; i++) fe_sq(t1, t1);
    fe_mul(t0, t1, t0);
    fe_sq(t1, t0); for (i = 1; i < 10; i++) fe_sq(t1, t1);
    fe_mul(t1, t1, t0);
    fe_sq(t2, t1); for (i = 1; i < 20; i++) fe_sq(t2, t2);
    fe_mul(t1, t2, t1);
    fe_sq(t1, t1); for (i = 1; i < 10; i++) fe_sq(t1, t1);
    fe_mul(t0, t1, t0);
    fe_sq(t1, t0); for (i = 1; i < 50; i++) fe_sq(t1, t1);
    fe_mul(t1, t1, t0);
    fe_sq(t2, t1); for (i = 1; i < 100; i++) fe_sq(t2, t2);
    fe_mul(t1, t2, t1);
    fe_sq(t1, t1); for (i = 1; i < 50; i++) fe_sq(t1, t1);
    fe_mul(t0, t1, t0);
    fe_sq(t0, t0); fe_sq(t0, t0);
    fe_mul(out, t0, z);
}

// out = 1/z, by Fermat: z^(p-2). 1/0 evaluates to 0.
__device__ __noinline__ void fe_invert(fe out, const fe z) {
    fe t0, t1, t2, t3;
    int i;
    fe_sq(t0, z);
    fe_sq(t1, t0); fe_sq(t1, t1);
    fe_mul(t1, z, t1);
    fe_mul(t0, t0, t1);
    fe_sq(t2, t0);
    fe_mul(t1, t1, t2);
    fe_sq(t2, t1); for (i = 1; i < 5; i++) fe_sq(t2, t2);
    fe_mul(t1, t2, t1);
    fe_sq(t2, t1); for (i = 1; i < 10; i++) fe_sq(t2, t2);
    fe_mul(t2, t2, t1);
    fe_sq(t3, t2); for (i = 1; i < 20; i++) fe_sq(t3, t3);
    fe_mul(t2, t3, t2);
    fe_sq(t2, t2); for (i = 1; i < 10; i++) fe_sq(t2, t2);
    fe_mul(t1, t2, t1);
    fe_sq(t2, t1); for (i = 1; i < 50; i++) fe_sq(t2, t2);
    fe_mul(t2, t2, t1);
    fe_sq(t3, t2); for (i = 1; i < 100; i++) fe_sq(t3, t3);
    fe_mul(t2, t3, t2);
    fe_sq(t2, t2); for (i = 1; i < 50; i++) fe_sq(t2, t2);
    fe_mul(t1, t2, t1);
    fe_sq(t1, t1); for (i = 1; i < 5; i++) fe_sq(t1, t1);
    fe_mul(out, t1, t0);
}

